import {readFileSync,writeFileSync} from 'node:fs';
import {hash,exact,insist,integer} from './core.mjs';
// No execution of the source or generated bytes. All offsets are byte offsets.
export function transform(input, contract, fixed) {
 exact(contract,['schemaVersion','head','tree','path','blob','sha256','start','end','anchor','contextStart','contextEnd','contextSha256','replacement','postSha256']);
 exact(fixed,['head','tree','path','blob','sha256']);
 insist(contract.schemaVersion===1,'UNKNOWN_SCHEMA');
 for(const k of Object.keys(fixed)) insist(contract[k]===fixed[k],'SOURCE_IDENTITY_MISMATCH');
 insist(Buffer.isBuffer(input),'INPUT_INVALID');
 insist(hash(input)===fixed.sha256 && createBlob(input)===fixed.blob,'SOURCE_HASH_MISMATCH');
 const {start,end,contextStart,contextEnd}=contract;
 insist([start,end,contextStart,contextEnd].every(integer)&&contextStart<=start&&start<end&&end<=contextEnd&&contextEnd<=input.length,'SPAN_INVALID');
 insist(typeof contract.anchor==='string'&&contract.anchor.length>0&&typeof contract.replacement==='string','ANCHOR_INVALID');
 const anchor=Buffer.from(contract.anchor); let count=0,at=0;
 while((at=input.indexOf(anchor,at))>=0){count++;at++;}
 insist(count===1,'ANCHOR_AMBIGUOUS');
 insist(input.subarray(start,end).equals(anchor),'PREIMAGE_MISMATCH');
 insist(hash(input.subarray(contextStart,contextEnd))===contract.contextSha256,'CONTEXT_MISMATCH');
 const output=Buffer.concat([input.subarray(0,start),Buffer.from(contract.replacement),input.subarray(end)]);
 insist(hash(output)===contract.postSha256,'POSTIMAGE_MISMATCH'); return output;
}
import {createHash} from 'node:crypto';
export function createBlob(b){return createHash('sha1').update(`blob ${b.length}\0`).update(b).digest('hex');}
export function transformFile(source,output,contract,fixed){
 insist(source!==output,'OUTPUT_IS_INPUT'); const original=readFileSync(source);const result=transform(original,contract,fixed);
 writeFileSync(output,result,{flag:'wx'});insist(readFileSync(source).equals(original),'INPUT_MUTATION');return {sha256:hash(result),size:result.length};
}
